        }
      } for (std::list<OGRLinearRing *>::iterator current_ring = rings_for_polygon.begin(); current_ring != rings_for_polygon.end(); ++current_ring)
        if ((*current_ring)->isClockwise()) new_polygon->addRingDirectly(*current_ring);
