      geometry = new_polygon;
    }

    else geometry = out_geometries;
  }

  void repair() {
    if (geometry->Is3D()) compute_plane();
    insert_constraints_in_triangulation(geometry);
    if (triangulation.number_of_faces() == 0) {
      geometry = NULL;
      return;
    } label_triangles();
    reconstruct();
  }
